import { chromium } from 'playwright';
import crypto from 'node:crypto';
import fs from 'node:fs';
const base=process.env.SUPABASE_URL,key=process.env.SUPABASE_PUBLISHABLE_KEY,runtime=process.env.RUNTIME_URL,spaceId=process.env.NAYA_EXISTING_SPACE_ID;
const project='NayaNET-WaveA-SmartMailResume-'+process.env.GITHUB_RUN_ID+'-'+crypto.randomBytes(4).toString('hex');
async function req(url,opt={}){const r=await fetch(url,opt);const t=await r.text();let b;try{b=JSON.parse(t)}catch{b={raw:t}}if(!r.ok)throw Error(r.status+' '+JSON.stringify(b));return b}
const h=t=>({apikey:key,authorization:'Bearer '+t,'content-type':'application/json'});
const signup=()=>req(base+'/auth/v1/signup',{method:'POST',headers:{apikey:key,'content-type':'application/json'},body:'{}'});
const A=await signup(),B=await signup(),C=await signup();
if(!A.access_token||!B.access_token||!C.access_token)throw Error('AUTH_BOOTSTRAP_FAILED');
const join=async u=>req(base+'/rest/v1/rpc/nayanet_join_space',{method:'POST',headers:h(u.access_token),body:JSON.stringify({p_space_id:spaceId})});
await join(A);await join(B);await join(C);
const save=async(u,target)=>req(base+'/rest/v1/rpc/nayanet_save_connection',{method:'POST',headers:h(u.access_token),body:JSON.stringify({p_target_member_id:target,p_space_id:spaceId})});
await save(A,B.user.id);await save(B,A.user.id);
const grant=await req(base+'/rest/v1/rpc/nayanet_issue_authority_grant',{method:'POST',headers:h(A.access_token),body:JSON.stringify({p_subject_id:A.user.id,p_source_event_id:'wavea-smart-mail-resume-'+project,p_mission_id:'Wave A Smart Mail resume acceptance',p_scope:{project_id:'NayaNET',target:B.user.id,space_id:spaceId},p_actions:['smart_mail_send'],p_constraints:{mode:'human-facing-acceptance',no_external_side_effects:true},p_expires_at:new Date(Date.now()+15*60*1000).toISOString(),p_evidence:{authorization_type:'explicit_wave_a_smart_mail_resume',space_id:spaceId},p_parent_authority:null})});
if(!grant?.grant_id)throw Error('AUTHORITY_GRANT_FAILED');
const browser=await chromium.launch({headless:true});
async function contextFor(session){const origin=new URL(runtime).origin;const storageState={cookies:[],origins:[{origin,localStorage:[{name:'nayanet.supabase.auth',value:JSON.stringify(session)}]}]};const c=await browser.newContext({storageState});const p=await c.newPage();await p.goto(runtime+'/',{waitUntil:'domcontentloaded',timeout:60000});await p.waitForFunction(()=>!!window.NayaAssistantRuntime,{timeout:30000});const auth=await p.evaluate(async({base,key})=>{const sdk=await import('https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2/+esm');const c=sdk.createClient(base,key,{auth:{persistSession:true,autoRefreshToken:true,storage:localStorage,storageKey:'nayanet.supabase.auth'}});const r=await c.auth.getUser();if(r.error)throw r.error;return r.data.user?.id},{base,key});if(auth!==session.user.id)throw Error('BROWSER_SESSION_HANDOFF_MISMATCH');return p}
const ap=await contextFor(A);
const auth=await ap.evaluate(()=>window.NayaAssistantRuntime.init());if(auth.user_id!==A.user.id||!auth.authenticated)throw Error('A_AUTHENTICATED_HANDOFF_FAILED');
const connections=await ap.evaluate(()=>window.NayaAssistantRuntime.listConnections());if(!connections.some(x=>x.connected_member_id===B.user.id&&x.status==='active'))throw Error('CONNECTION_PREREQUISITE_FAILED');
const network=[];ap.on('request',x=>{if(x.url().includes('smart-mail')||x.url().includes('/functions/'))network.push({type:'request',url:x.url(),method:x.method(),origin:x.headers()['origin']})});ap.on('response',x=>{if(x.url().includes('smart-mail')||x.url().includes('/functions/'))network.push({type:'response',url:x.url(),status:x.status(),allowOrigin:x.headers()['access-control-allow-origin'],contentType:x.headers()['content-type']})});ap.on('requestfailed',x=>{if(x.url().includes('smart-mail')||x.url().includes('/functions/'))network.push({type:'requestfailed',url:x.url(),failure:x.failure()?.errorText||null})});
const mail=await ap.evaluate(async x=>window.NayaAssistantRuntime.sendSmartMail({receiver_id:x.receiver,body:'Wave A Smart Mail resume acceptance.',subject:'Wave A Smart Mail resume',authority_grant_id:x.grant,idempotency_key:x.key}),{receiver:B.user.id,grant:grant.grant_id,key:'wavea-smart-mail-resume-'+project});
if(!mail?.message_id)throw Error('SMART_MAIL_UI_FAILED');
const ta=await ap.evaluate(()=>window.NayaAssistantRuntime.listMailThreads());if(!ta.some(x=>x.id===mail.thread_id))throw Error('SMART_MAIL_RENDER_FAILED');
const bp=await contextFor(B);if((await bp.evaluate(()=>window.NayaAssistantRuntime.init())).user_id!==B.user.id)throw Error('B_AUTH_HANDOFF_FAILED');
if(!(await bp.evaluate(id=>window.NayaAssistantRuntime.verifySmartMail(id),mail.message_id))?.ok)throw Error('B_RECEIVER_VERIFICATION_UI_FAILED');
if(!(await bp.evaluate(()=>window.NayaAssistantRuntime.listMailThreads())).some(x=>x.id===mail.thread_id))throw Error('B_RETRIEVAL_UI_FAILED');
if(!Array.isArray(await bp.evaluate(()=>window.NayaAssistantRuntime.retrieve())))throw Error('INTELLIGENCE_UI_FAILED');
const cp=await contextFor(C);if((await cp.evaluate(()=>window.NayaAssistantRuntime.init())).user_id!==C.user.id)throw Error('C_AUTH_HANDOFF_FAILED');
if((await cp.evaluate(()=>window.NayaAssistantRuntime.listMailThreads())).some(x=>x.id===mail.thread_id))throw Error('C_ISOLATION_UI_FAILED');
const receipt={schema:'nayanet.wave-a.smart-mail-resume.v1',status:'VERIFIED',run_id:process.env.GITHUB_RUN_ID,project,space_id:spaceId,checks:{smart_mail:'PASS',smart_mail_render:'PASS',b_receiver_verification:'PASS',b_retrieval:'PASS',intelligence_retrieval:'PASS',c_isolation:'PASS'},identities:{A:A.user.id,B:B.user.id,C:C.user.id},message_id:mail.message_id,thread_id:mail.thread_id,network};
fs.writeFileSync(process.env.RUNNER_TEMP+'/wave-a-smart-mail-resume.json',JSON.stringify(receipt,null,2));
console.log('WAVE_A_SMART_MAIL_RESUME=PASS');console.log(JSON.stringify(receipt));await browser.close();